<?php

declare(strict_types=1);

namespace OpenTelemetry\Contrib\Ci;

/**
 * Each project's CI badge, required in its README, and the project
 * list --generate writes into the root README. See README.md in
 * .github/ci.
 */
final class Badges
{
    public const START = '<!-- Generated by .github/ci/matrix.php --generate. Do not edit. -->';
    public const END = '<!-- End of generated project list. -->';

    // Split repositories publish the READMEs, so badges link back here.
    private const ACTIONS = 'https://github.com/open-telemetry/opentelemetry-php-contrib/actions/workflows';

    public static function badge(Project $project): string
    {
        $workflow = self::ACTIONS . '/' . basename(Workflows::path($project));

        return "[![CI]($workflow/badge.svg?branch=main)]($workflow?query=branch%3Amain)";
    }

    /**
     * The root README with its project list rewritten, or null when it
     * has no START marker followed by an END marker.
     *
     * @param list<Project> $projects the projects CI runs
     */
    public static function updateRoot(string $readme, array $projects): ?string
    {
        $start = strpos($readme, self::START . "\n");
        $end = strpos($readme, self::END);
        if ($start === false || $end === false || $end < $start) {
            return null;
        }
        usort($projects, fn (Project $a, Project $b) => strcmp($a->name, $b->name));
        $list = "| Project | CI |\n|---|---|\n";
        foreach ($projects as $project) {
            $list .= sprintf("| [%s](src/%s) | %s |\n", $project->name, $project->name, self::badge($project));
        }
        $from = $start + strlen(self::START . "\n");

        return substr($readme, 0, $from) . $list . substr($readme, $end);
    }

    /**
     * Projects whose README lacks its badge, and a root project list
     * that is missing or stale, as GitHub annotations.
     *
     * @param list<Project> $projects the projects CI runs
     * @param array<string, string> $readmes project READMEs, by path
     * @param string $root the root README
     * @return list<string>
     */
    public static function problems(array $projects, array $readmes, string $root): array
    {
        $problems = [];
        foreach ($projects as $project) {
            $path = "src/$project->name/README.md";
            $badge = self::badge($project);
            if (!str_contains($readmes[$path] ?? '', $badge)) {
                $problems[] = self::error($path, "$path has no CI badge. Add this line: $badge");
            }
        }

        $expected = self::updateRoot($root, $projects);
        if ($expected === null) {
            $problems[] = self::noProjectList();
        } elseif ($expected !== $root) {
            $problems[] = self::error('README.md', "README.md's project list differs from what matrix.php generates. Run make ci-generate.");
        }

        return $problems;
    }

    // For when updateRoot() returns null.
    public static function noProjectList(): string
    {
        return self::error('README.md', sprintf('README.md has no generated project list. Add the lines %s and %s, then run make ci-generate.', self::START, self::END));
    }

    private static function error(string $file, string $message): string
    {
        return "::error file=$file::$message";
    }
}
